"""Build purchase reorder files from inventory CSV inputs."""

from __future__ import annotations

import argparse
import csv
import json
import sys
from collections import defaultdict
from dataclasses import dataclass
from datetime import date, timedelta
from decimal import Decimal, localcontext
from pathlib import Path
from typing import Iterable


FORECAST_DAYS = 28
REORDER_HEADER = [
    "sku",
    "warehouse",
    "forecast_daily",
    "target_qty",
    "on_hand",
    "eligible_open_po",
    "reorder_qty",
    "supplier_id",
    "case_pack",
    "order_cases",
    "arrival_date",
]


class InputError(ValueError):
    """Raised when an input file does not follow the required schema."""


@dataclass(frozen=True)
class Product:
    sku: str
    supplier_id: str
    case_pack: int
    lead_days: int
    safety_days: int


@dataclass
class OrderLine:
    sku: str
    warehouse: str
    product: Product
    demand_total: int
    on_hand: int
    eligible_open_po: int
    uncovered_numerator: int
    order_cases: int
    padding_units: int = 0

    @property
    def quantity(self) -> int:
        return self.order_cases * self.product.case_pack

    @property
    def arrival_date(self) -> date:
        return self._as_of + timedelta(days=self.product.lead_days)

    # Set once during construction; excluded from the public constructor fields
    # would require a more complicated custom initializer.
    _as_of: date = date.min


def read_csv(path: Path, expected_header: list[str]) -> list[dict[str, str]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as handle:
            reader = csv.DictReader(handle)
            if reader.fieldnames != expected_header:
                raise InputError(
                    f"{path}: expected header {','.join(expected_header)!r}, "
                    f"got {','.join(reader.fieldnames or [])!r}"
                )
            rows = []
            for line_number, row in enumerate(reader, start=2):
                if None in row:
                    raise InputError(f"{path}:{line_number}: too many columns")
                if any(value is None for value in row.values()):
                    raise InputError(f"{path}:{line_number}: too few columns")
                rows.append(row)
            return rows
    except FileNotFoundError as exc:
        raise InputError(f"missing input file: {path}") from exc


def nonnegative_int(value: str, path: Path, line_number: int, field: str) -> int:
    try:
        result = int(value)
    except ValueError as exc:
        raise InputError(f"{path}:{line_number}: {field} must be a whole number") from exc
    if result < 0:
        raise InputError(f"{path}:{line_number}: {field} must be a non-negative whole number")
    return result


def positive_int(value: str, path: Path, line_number: int, field: str) -> int:
    result = nonnegative_int(value, path, line_number, field)
    if result == 0:
        raise InputError(f"{path}:{line_number}: {field} must be positive")
    return result


def parse_date(value: str, path: Path, line_number: int, field: str) -> date:
    try:
        return date.fromisoformat(value)
    except ValueError as exc:
        raise InputError(f"{path}:{line_number}: invalid {field}: {value!r}") from exc


def load_products(input_dir: Path) -> dict[str, Product]:
    path = input_dir / "products.csv"
    rows = read_csv(
        path, ["sku", "supplier_id", "case_pack", "lead_days", "safety_days"]
    )
    products: dict[str, Product] = {}
    for line_number, row in enumerate(rows, start=2):
        sku = row["sku"]
        if not sku or not row["supplier_id"]:
            raise InputError(f"{path}:{line_number}: SKU and supplier_id cannot be blank")
        if sku in products:
            raise InputError(f"{path}:{line_number}: duplicate SKU {sku!r}")
        products[sku] = Product(
            sku=sku,
            supplier_id=row["supplier_id"],
            case_pack=positive_int(row["case_pack"], path, line_number, "case_pack"),
            lead_days=nonnegative_int(row["lead_days"], path, line_number, "lead_days"),
            safety_days=nonnegative_int(row["safety_days"], path, line_number, "safety_days"),
        )
    return products


def load_suppliers(input_dir: Path) -> dict[str, int]:
    path = input_dir / "suppliers.json"
    try:
        with path.open("r", encoding="utf-8") as handle:
            raw = json.load(handle)
    except FileNotFoundError as exc:
        raise InputError(f"missing input file: {path}") from exc
    except json.JSONDecodeError as exc:
        raise InputError(f"{path}: invalid JSON: {exc.msg}") from exc
    if not isinstance(raw, list):
        raise InputError(f"{path}: top-level value must be an array")
    suppliers: dict[str, int] = {}
    for index, item in enumerate(raw):
        where = f"{path}: supplier entry {index + 1}"
        if not isinstance(item, dict) or set(item) != {"supplier_id", "minimum_cases"}:
            raise InputError(f"{where}: expected supplier_id and minimum_cases")
        supplier_id = item["supplier_id"]
        minimum = item["minimum_cases"]
        if not isinstance(supplier_id, str) or not supplier_id:
            raise InputError(f"{where}: supplier_id must be a non-empty string")
        if isinstance(minimum, bool) or not isinstance(minimum, int) or minimum < 0:
            raise InputError(f"{where}: minimum_cases must be a non-negative whole number")
        if supplier_id in suppliers:
            raise InputError(f"{where}: duplicate supplier_id {supplier_id!r}")
        suppliers[supplier_id] = minimum
    return suppliers


def load_stock(input_dir: Path, products: dict[str, Product]) -> dict[tuple[str, str], int]:
    path = input_dir / "stock.csv"
    rows = read_csv(path, ["sku", "warehouse", "on_hand"])
    stock: dict[tuple[str, str], int] = {}
    for line_number, row in enumerate(rows, start=2):
        key = (row["sku"], row["warehouse"])
        if key[0] not in products:
            raise InputError(f"{path}:{line_number}: unknown SKU {key[0]!r}")
        if not key[1]:
            raise InputError(f"{path}:{line_number}: warehouse cannot be blank")
        if key in stock:
            raise InputError(f"{path}:{line_number}: duplicate stock line {key!r}")
        stock[key] = nonnegative_int(row["on_hand"], path, line_number, "on_hand")
    return stock


def load_demand(
    input_dir: Path, products: dict[str, Product], as_of: date
) -> dict[tuple[str, str], int]:
    path = input_dir / "demand.csv"
    rows = read_csv(path, ["date", "sku", "warehouse", "quantity"])
    start = as_of - timedelta(days=FORECAST_DAYS)
    totals: defaultdict[tuple[str, str], int] = defaultdict(int)
    for line_number, row in enumerate(rows, start=2):
        demand_date = parse_date(row["date"], path, line_number, "date")
        sku = row["sku"]
        if sku not in products:
            raise InputError(f"{path}:{line_number}: unknown SKU {sku!r}")
        if not row["warehouse"]:
            raise InputError(f"{path}:{line_number}: warehouse cannot be blank")
        quantity = nonnegative_int(row["quantity"], path, line_number, "quantity")
        if start <= demand_date < as_of:
            totals[(sku, row["warehouse"])] += quantity
    return dict(totals)


def load_eligible_pos(
    input_dir: Path, products: dict[str, Product], as_of: date
) -> dict[tuple[str, str], int]:
    path = input_dir / "open_pos.csv"
    rows = read_csv(path, ["po_id", "sku", "warehouse", "quantity", "arrival_date"])
    totals: defaultdict[tuple[str, str], int] = defaultdict(int)
    for line_number, row in enumerate(rows, start=2):
        sku = row["sku"]
        if sku not in products:
            raise InputError(f"{path}:{line_number}: unknown SKU {sku!r}")
        if not row["po_id"] or not row["warehouse"]:
            raise InputError(f"{path}:{line_number}: po_id and warehouse cannot be blank")
        quantity = nonnegative_int(row["quantity"], path, line_number, "quantity")
        arrival = parse_date(row["arrival_date"], path, line_number, "arrival_date")
        if arrival <= as_of + timedelta(days=products[sku].lead_days):
            totals[(sku, row["warehouse"])] += quantity
    return dict(totals)


def ceil_div(numerator: int, denominator: int) -> int:
    return (numerator + denominator - 1) // denominator


def build_lines(
    products: dict[str, Product],
    stock: dict[tuple[str, str], int],
    demand: dict[tuple[str, str], int],
    eligible_pos: dict[tuple[str, str], int],
    as_of: date,
) -> list[OrderLine]:
    lines = []
    for (sku, warehouse), on_hand in sorted(stock.items()):
        product = products[sku]
        demand_total = demand.get((sku, warehouse), 0)
        eligible_po = eligible_pos.get((sku, warehouse), 0)
        position = on_hand + eligible_po
        target_numerator = demand_total * (product.lead_days + product.safety_days)
        uncovered_numerator = max(0, target_numerator - FORECAST_DAYS * position)
        whole_units = ceil_div(uncovered_numerator, FORECAST_DAYS)
        cases = ceil_div(whole_units, product.case_pack)
        lines.append(
            OrderLine(
                sku=sku,
                warehouse=warehouse,
                product=product,
                demand_total=demand_total,
                on_hand=on_hand,
                eligible_open_po=eligible_po,
                uncovered_numerator=uncovered_numerator,
                order_cases=cases,
                _as_of=as_of,
            )
        )
    return lines


def apply_supplier_minimums(
    lines: Iterable[OrderLine], suppliers: dict[str, int]
) -> None:
    grouped: defaultdict[str, list[OrderLine]] = defaultdict(list)
    for line in lines:
        if line.order_cases:
            grouped[line.product.supplier_id].append(line)

    for supplier_id, candidates in grouped.items():
        minimum = suppliers[supplier_id]
        total_cases = sum(line.order_cases for line in candidates)
        while total_cases < minimum:
            # Compare exact rational scores. Every uncovered value has the same
            # denominator (28), so scaled integer numerators preserve ordering.
            selected = min(
                candidates,
                key=lambda line: (
                    -max(
                        0,
                        line.uncovered_numerator
                        - FORECAST_DAYS * line.padding_units,
                    ),
                    line.sku,
                    line.warehouse,
                ),
            )
            selected.order_cases += 1
            selected.padding_units += selected.product.case_pack
            total_cases += 1


def decimal_four(numerator: int, denominator: int = FORECAST_DAYS) -> str:
    # Keep enough precision even when a caller supplies unusually large unit
    # counts; Decimal's default 28 digits should not constrain valid integers.
    with localcontext() as context:
        context.prec = max(28, len(str(abs(numerator))) + 10)
        return format(Decimal(numerator) / Decimal(denominator), ".4f")


def write_outputs(
    output_dir: Path,
    lines: list[OrderLine],
    suppliers: dict[str, int],
    as_of: date,
) -> None:
    output_dir.mkdir(parents=True, exist_ok=True)
    reorder_path = output_dir / "reorder.csv"
    with reorder_path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, lineterminator="\n")
        writer.writerow(REORDER_HEADER)
        for line in lines:
            horizon = line.product.lead_days + line.product.safety_days
            writer.writerow(
                [
                    line.sku,
                    line.warehouse,
                    decimal_four(line.demand_total),
                    decimal_four(line.demand_total * horizon),
                    line.on_hand,
                    line.eligible_open_po,
                    line.quantity,
                    line.product.supplier_id,
                    line.product.case_pack,
                    line.order_cases,
                    line.arrival_date.isoformat() if line.quantity else "",
                ]
            )

    ordered_suppliers = []
    supplier_ids = sorted(
        {line.product.supplier_id for line in lines if line.order_cases}
    )
    for supplier_id in supplier_ids:
        supplier_lines = sorted(
            (
                line
                for line in lines
                if line.product.supplier_id == supplier_id and line.order_cases
            ),
            key=lambda line: (line.sku, line.warehouse),
        )
        ordered_suppliers.append(
            {
                "supplier_id": supplier_id,
                "minimum_cases": suppliers[supplier_id],
                "total_cases": sum(line.order_cases for line in supplier_lines),
                "lines": [
                    {
                        "sku": line.sku,
                        "warehouse": line.warehouse,
                        "quantity": line.quantity,
                        "cases": line.order_cases,
                        "arrival_date": line.arrival_date.isoformat(),
                    }
                    for line in supplier_lines
                ],
            }
        )

    payload = {"as_of": as_of.isoformat(), "suppliers": ordered_suppliers}
    json_path = output_dir / "supplier_orders.json"
    with json_path.open("w", encoding="utf-8", newline="\n") as handle:
        json.dump(payload, handle, ensure_ascii=False, indent=2)
        handle.write("\n")


def run(input_dir: Path, output_dir: Path, as_of: date) -> None:
    products = load_products(input_dir)
    suppliers = load_suppliers(input_dir)
    missing = sorted(
        {product.supplier_id for product in products.values()} - suppliers.keys()
    )
    if missing:
        raise InputError(f"products reference unknown suppliers: {', '.join(missing)}")
    stock = load_stock(input_dir, products)
    demand = load_demand(input_dir, products, as_of)
    eligible_pos = load_eligible_pos(input_dir, products, as_of)
    lines = build_lines(products, stock, demand, eligible_pos, as_of)
    apply_supplier_minimums(lines, suppliers)
    write_outputs(output_dir, lines, suppliers, as_of)


def make_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input_dir", type=Path, help="directory containing input files")
    parser.add_argument("--as-of", required=True, help="planning date in YYYY-MM-DD format")
    parser.add_argument("--output", required=True, type=Path, help="output directory")
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = make_parser()
    args = parser.parse_args(argv)
    try:
        as_of = date.fromisoformat(args.as_of)
    except ValueError:
        parser.error(f"invalid --as-of date: {args.as_of!r}")
    try:
        run(args.input_dir, args.output, as_of)
    except (InputError, OSError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

